import games from "@/data/dynawalla-games.json";
import { artOf, hueClass } from "@/lib/dynawalla/art";
import { shapesOf, type Shape } from "@/lib/dynawalla/motifs";

/**
 * The Dynawalla catalogue, as the site sees it.
 *
 * `data/dynawalla-games.json` is generated by
 * `web/scripts/generate-dynawalla-games.js` from each game's own
 * `dynawalla/games/<game>/pack.json` — the same manifest the app packages and
 * ships. Every name, description and skill below is the pack's own words, not
 * marketing copy written about it. It regenerates on every build, so do not
 * edit the JSON or restate any of it as prose here.
 */
export interface DynawallaGame {
  readonly id: string;
  readonly slug: string;
  readonly name: string;
  readonly description: string;
  readonly version: string;
  readonly minAge: number | null;
  readonly skills: readonly string[];
  /** Whether `public/dynawalla/shots/<slug>.webp` exists. Detected at build. */
  readonly hasShot: boolean;
}

export const DYNAWALLA_GAMES = games as unknown as DynawallaGame[];

export function getGame(slug: string): DynawallaGame | undefined {
  return DYNAWALLA_GAMES.find((g) => g.slug === slug);
}

const NUMBER_WORDS = [
  "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
  "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
  "sixteen", "seventeen", "eighteen", "nineteen", "twenty",
];

/**
 * How many games there are, spelled out, for use in prose.
 *
 * Never write the number in copy. The App Store description said "Twenty-seven
 * games" for weeks after the catalogue had settled at twenty-five, because a
 * count written by hand has nothing that fails when it stops being true. This
 * reads the generated catalogue, so it cannot drift from it.
 */
export function gameCountWord(): string {
  const n = DYNAWALLA_GAMES.length;
  if (n <= 20) return NUMBER_WORDS[n];
  if (n < 100) {
    const tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty",
      "seventy", "eighty", "ninety"][Math.floor(n / 10)];
    const ones = n % 10;
    return ones === 0 ? tens : `${tens}-${NUMBER_WORDS[ones]}`;
  }
  return String(n);
}

/** The same, with an initial capital, for the start of a sentence or heading. */
export function gameCountWordTitle(): string {
  const word = gameCountWord();
  return word.charAt(0).toUpperCase() + word.slice(1);
}

/* ------------------------------------------------------------------ *
 * Subjects
 *
 * Derived from the skill id, exactly as the app derives them: the second
 * segment of `dw.add.column.add-no-regroup` is the subject. There is
 * deliberately no per-game table — a game whose subject this build has never
 * heard of keeps every other subject it matches rather than vanishing.
 * ------------------------------------------------------------------ */

export const DOMAIN_IDS = ["ns", "add", "mul", "div", "frac", "alg"] as const;
export type DomainId = (typeof DOMAIN_IDS)[number];

export const DOMAIN_NAMES: Record<DomainId, string> = {
  ns: "Number sense",
  add: "Addition & subtraction",
  mul: "Multiplication",
  div: "Division",
  frac: "Fractions",
  alg: "Equality & algebra",
};

const isDomainId = (value: string): value is DomainId =>
  (DOMAIN_IDS as readonly string[]).includes(value);

export function domainOfSkill(skill: string): DomainId | null {
  const parts = skill.split(".");
  if (parts.length < 2 || parts[0] !== "dw") return null;
  const second = parts[1] ?? "";
  return isDomainId(second) ? second : null;
}

export function domainsOf(skills: readonly string[]): readonly DomainId[] {
  const found = new Set<DomainId>();
  for (const skill of skills) {
    const domain = domainOfSkill(skill);
    if (domain !== null) found.add(domain);
  }
  return DOMAIN_IDS.filter((d) => found.has(d));
}

