/**
 * A skill's name. A skill this build has never heard of falls back to its own
 * last segment rather than disappearing — the same posture the app takes with
 * an unknown subject.
 */
export function skillLabel(skill: string): string {
  const known = SKILL_LABELS[skill];
  if (known) return known;
  const last = skill.split(".").pop() ?? skill;
  const words = last.replace(/-/g, " ");
  return words.charAt(0).toUpperCase() + words.slice(1);
}

/* ------------------------------------------------------------------ *
 * Screenshots
 *
 * Captured from the real build in the iOS Simulator. `hasShot` is DETECTED by
 * the generator from the presence of `public/dynawalla/shots/<slug>.webp`, not
 * declared, so adding or deleting a file is the whole change. A game without
 * one shows its key art alone rather than a placeholder or another game\'s
 * picture.
 * ------------------------------------------------------------------ */
export function shotFor(slug: string): string | null {
  const game = DYNAWALLA_GAMES.find((g) => g.slug === slug);
  return game?.hasShot ? `/dynawalla/shots/${slug}.webp` : null;
}

/**
 * The absolute image to show when a page is shared.
 *
 * Next replaces a parent's `openGraph` wholesale rather than merging it, so a
 * page that sets `openGraph` without `images` ends up with NO og:image — which
 * is what every game page shipped with. This always resolves: the game's own
 * screenshot where one was captured, and the catalogue otherwise.
 */
export function ogImageFor(slug: string): string {
  const shot = shotFor(slug);
  return `https://encorpora.io${shot ?? "/dynawalla/shots/catalog.webp"}`;
}

/* ------------------------------------------------------------------ *
 * Key art
 * ------------------------------------------------------------------ */

export interface GameArt {
  readonly hueClassName: string;
  readonly shapes: readonly Shape[];
}

/**
 * The same picture the app draws, computed the same way.
 *
 * `artOf` hashes the pack id into a hue and a motif; `shapesOf` turns the
 * motif into geometry through a seeded PRNG. Both are pure, so the card on
 * this page and the card on a phone are the same drawing.
 */
export function artFor(packId: string): GameArt {
  const spec = artOf(packId);
  return {
    hueClassName: hueClass(spec.hue),
    shapes: shapesOf(spec.motif, rngFor(spec.seed)),
  };
}

function rngFor(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
